package br.com.folha.notes;
import android.app.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.ExecutorService;

/** One optional background job; raw ink stays authoritative until a checked, undoable replacement. */
final class JapaneseAssist implements AutoCloseable {
 static final int OFF=0,ADJUST=1,REGULAR=2;
 static final String[] NAMES={"Desligado","Traços ajustados","Regular"};
 final MainActivity a;final ExecutorService worker=MainActivity.background("folha-japanese");
 final LinkedHashMap<String,Group> groups=new LinkedHashMap<>();
 NotebookView view;JapaneseRecognizer engine;int mode,epoch;boolean busy,preparing,modelReady,applying,closed;long lastInput;
 String message="";TextView status;LinearLayout candidates;HorizontalScrollView bar;Group last;
 final Runnable idle=this::drain;
 static final class Group {String key;final List<Ink.Stroke> raw=new ArrayList<>();List<Ink.Stroke> output;List<String> choices=Collections.emptyList();float[] cell,box;int serial;boolean skipped;long updated;}
 JapaneseAssist(MainActivity a){this.a=a;mode=Math.max(0,Math.min(2,a.getSharedPreferences("japanese",0).getInt("mode",0)));}
 void attach(NotebookView next){cancel();view=next;next.assist=this;if(mode==REGULAR)prepare(false);refresh();}
 void detach(NotebookView previous){if(view==previous){cancel();view=null;status=null;candidates=null;bar=null;}}
 void cancel(){epoch++;busy=false;groups.clear();last=null;a.main.removeCallbacks(idle);message="";refresh();}
 void edited(){if(!applying)cancel();}
 void setMode(int selected){if(selected<0||selected>2)return;mode=selected;cancel();a.getSharedPreferences("japanese",0).edit().putInt("mode",mode).apply();if(mode!=REGULAR&&engine!=null){engine.close();engine=null;modelReady=false;preparing=false;}if(mode==REGULAR)prepare(true);refresh();}
 void prepare(boolean download){if(closed||mode!=REGULAR||preparing)return;try{if(engine==null)engine=new JapaneseRecognizer(worker);JapaneseRecognizer current=engine;preparing=true;message=download?"Preparando modelo japonês…":"Verificando modelo…";refresh();current.prepare(download,error->a.main.post(()->{if(closed||engine!=current||mode!=REGULAR)return;preparing=false;modelReady=error==null;message=error==null?"Pronto · um caractere por vez":download?"Falha no download · toque para tentar novamente":"Toque para baixar o modelo (~20 MB)";refresh();if(modelReady)schedule();}));}catch(Exception e){preparing=false;message="Modelo indisponível · toque para tentar novamente";refresh();}}
 void show(){LinearLayout box=a.column();box.setPadding(a.dp(22),a.dp(8),a.dp(22),a.dp(12));RadioGroup choices=new RadioGroup(a);for(int i=0;i<3;i++){RadioButton option=new RadioButton(a);option.setText(NAMES[i]);option.setId(100+i);choices.addView(option);}choices.check(100+mode);choices.setOnCheckedChangeListener((g,id)->setMode(id-100));box.addView(choices);TextView note=a.text("Traços ajustados suaviza e endireita sua escrita; não corrige o significado do kanji.\n\nRegular reconhece um kana ou kanji por vez após uma pausa de 1,8 s. No primeiro uso, baixa o modelo japonês (~20 MB); depois reconhece offline. Prefira as quadrículas japonesas.\n\nSe a sugestão estiver errada, escolha outra na faixa ou toque em Original. Dois dedos desfazem. Começar outro traço no mesmo caractere reabre o original.",13,MainActivity.MUTED,false);box.addView(note);a.dialog().setTitle("Auxílio de kana e kanji").setView(box).setNegativeButton("Fechar",null).setNeutralButton("Baixar / tentar novamente",(d,w)->{if(mode!=REGULAR)setMode(REGULAR);else prepare(true);}).show();}
 HorizontalScrollView controls(){bar=new HorizontalScrollView(a);bar.setHorizontalScrollBarEnabled(false);LinearLayout row=a.row();row.setPadding(a.dp(14),0,a.dp(12),0);status=a.text("",12,MainActivity.GREEN,true);status.setSingleLine();status.setMaxWidth(a.dp(320));status.setEllipsize(android.text.TextUtils.TruncateAt.END);status.setMinHeight(a.dp(42));status.setOnClickListener(v->show());row.addView(status);candidates=a.row();row.addView(candidates);bar.addView(row);refresh();return bar;}
 void refresh(){if(bar!=null)bar.setVisibility(mode==OFF?View.GONE:View.VISIBLE);if(a.japaneseButton!=null)a.japaneseButton.setText(mode==OFF?"あ 漢":"あ 漢 · "+(mode==ADJUST?"Traços":"Regular"));if(status!=null)status.setText(NAMES[mode]+" · "+(message.isEmpty()?"pausa de 1,8 s":message));if(candidates!=null){candidates.removeAllViews();Group group=last;if(group!=null&&group.output!=null){for(String text:group.choices){TextView b=a.button(text,false,()->choose(group,text));b.setTextLocale(Locale.JAPANESE);b.setMinHeight(a.dp(36));b.setPadding(a.dp(12),a.dp(3),a.dp(12),a.dp(3));b.setContentDescription("Usar caractere "+text);candidates.addView(b);a.gap(candidates,5);}TextView original=a.button("Original",false,()->restore(group,true));original.setMinHeight(a.dp(36));original.setPadding(a.dp(10),a.dp(3),a.dp(10),a.dp(3));candidates.addView(original);}}}
 void down(float x,float y,boolean ink){if(mode==OFF||view==null)return;lastInput=android.os.SystemClock.uptimeMillis();a.main.removeCallbacks(idle);if(!ink){cancel();return;}float[] cell=JapaneseGeometry.cell(view.paper,view.pageW,view.pageH,x,y);for(Group g:new ArrayList<>(groups.values())){if(g.output==null)continue;float[] b=g.cell==null?g.box:g.cell;float pad=g.cell==null?8:0;if(x>=b[0]-pad&&x<=b[2]+pad&&y>=b[1]-pad&&y<=b[3]+pad&&lastInput-g.updated<30000){if(cell==null||g.cell==null||Arrays.equals(cell,g.cell)){restore(g,false);break;}}}}
 void committed(Ink.Stroke stroke){if(mode==OFF||view==null||closed||stroke.marker||!stroke.glyph.isEmpty()||!stroke.kind.equals("ink"))return;lastInput=android.os.SystemClock.uptimeMillis();float[] b=JapaneseGeometry.bounds(Collections.singletonList(stroke));float[] cell=JapaneseGeometry.cell(view.paper,view.pageW,view.pageH,(b[0]+b[2])/2,(b[1]+b[3])/2);if(cell!=null&&(b[2]-b[0]>(cell[2]-cell[0])*1.3f||b[3]-b[1]>(cell[3]-cell[1])*1.3f))return;
  String key=cell==null?null:Arrays.toString(cell);Group g=key==null?null:groups.get(key);if(g!=null&&g.output!=null)g=null;if(cell==null&&last!=null&&last.cell==null&&last.output==null&&JapaneseGeometry.near(last.box,b))g=last;if(g==null){g=new Group();g.key=key==null?UUID.randomUUID().toString():key;g.cell=cell;groups.put(g.key,g);}g.raw.add(stroke);if(g.box==null)g.box=b.clone();else{g.box[0]=Math.min(g.box[0],b[0]);g.box[1]=Math.min(g.box[1],b[1]);g.box[2]=Math.max(g.box[2],b[2]);g.box[3]=Math.max(g.box[3],b[3]);}g.serial++;g.skipped=false;g.updated=lastInput;last=g;int points=0;for(Ink.Stroke s:g.raw)points+=s.points.size();if(g.raw.size()>64||points>16000)g.skipped=true;while(groups.size()>32){String first=groups.keySet().iterator().next();groups.remove(first);}message=mode==REGULAR&&!modelReady?message:"Escrevendo…";schedule();refresh();
 }
 void schedule(){a.main.removeCallbacks(idle);if(mode!=OFF&&!closed)a.main.postDelayed(idle,1800);}
 boolean valid(Group g,List<Ink.Stroke> raw,int serial,int token){return !closed&&view!=null&&a.canvas==view&&epoch==token&&groups.get(g.key)==g&&g.serial==serial&&g.output==null&&raw.stream().allMatch(view.strokes::contains);}
 void drain(){if(closed||mode==OFF||view==null||busy)return;if(view.writing()||android.os.SystemClock.uptimeMillis()-lastInput<1700){schedule();return;}if(mode==REGULAR&&!modelReady)return;Group group=null;for(Group g:groups.values())if(g.output==null&&!g.skipped&&!g.raw.isEmpty()){group=g;break;}if(group==null)return;final Group g=group;final List<Ink.Stroke> raw=new ArrayList<>(g.raw);final int serial=g.serial,token=epoch,chosenMode=mode;busy=true;
  if(mode==ADJUST)worker.execute(()->{try{List<Ink.Stroke> adjusted=JapaneseGeometry.adjust(raw,g.cell);a.main.post(()->finish(g,raw,serial,token,chosenMode,adjusted,Collections.emptyList(),null));}catch(Exception e){a.main.post(()->finish(g,raw,serial,token,chosenMode,null,Collections.emptyList(),e));}});
  else {JapaneseRecognizer current=engine;worker.execute(()->current.recognize(raw,(choices,error)->{List<Ink.Stroke> out=null;Exception failure=error;if(failure==null&&!choices.isEmpty())try{out=Collections.singletonList(JapaneseGlyph.regular(choices.get(0),raw,g.cell));}catch(Exception e){failure=e;}final List<Ink.Stroke> result=out;final Exception err=failure;a.main.post(()->finish(g,raw,serial,token,chosenMode,result,choices,err));}));}
 }
 void finish(Group g,List<Ink.Stroke> raw,int serial,int token,int chosenMode,List<Ink.Stroke> out,List<String> choices,Exception error){if(token==epoch)busy=false;if(!valid(g,raw,serial,token)||mode!=chosenMode){schedule();return;}if(view.writing()){schedule();return;}if(error!=null||out==null||out.isEmpty()){g.skipped=true;message=error==null?"Não reconhecido · mantenha um caractere por vez":"Não foi possível ajustar · original preservado";}else{replace(raw,out);g.output=out;g.choices=choices;g.updated=android.os.SystemClock.uptimeMillis();last=g;message=chosenMode==ADJUST?"Traços alinhados":choices.get(0)+" · toque para escolher outra opção";}refresh();a.main.removeCallbacks(idle);a.main.postDelayed(idle,150);}
 void replace(List<Ink.Stroke> before,List<Ink.Stroke> after){int index=view.strokes.indexOf(before.get(0));if(index<0)return;view.history.before(view.strokes);view.strokes.removeAll(before);view.strokes.addAll(Math.min(index,view.strokes.size()),after);applying=true;try{view.selection.clear();view.documentChanged();}finally{applying=false;}}
 void restore(Group g,boolean block){if(view==null||g.output==null||!view.strokes.containsAll(g.output))return;replace(g.output,g.raw);g.output=null;g.serial++;g.skipped=block;message="Escrita original restaurada";last=g;refresh();}
 void choose(Group g,String text){if(view==null||g.output==null||!view.strokes.containsAll(g.output))return;final int serial=g.serial,token=epoch;final List<Ink.Stroke> previous=g.output;worker.execute(()->{try{Ink.Stroke next=JapaneseGlyph.regular(text,g.raw,g.cell);a.main.post(()->{if(view==null||closed||view.writing()||epoch!=token||g.serial!=serial||g.output!=previous||!view.strokes.containsAll(previous))return;replace(previous,Collections.singletonList(next));g.output=Collections.singletonList(next);message=text+" · ajustado";refresh();});}catch(Exception e){a.main.post(()->a.toast("Caractere indisponível. O original foi preservado."));}});}
 @Override public void close(){closed=true;cancel();if(engine!=null)engine.close();worker.shutdown();}
}
